    private static void Probe(string name, ITimerService service, bool dispose)
    {
        using var firstEntered = new ManualResetEventSlim();
        using var cancelEntered = new ManualResetEventSlim();
        using var releaseCancel = new ManualResetEventSlim();
        using var cancelReturned = new ManualResetEventSlim();
        using var secondEntered = new ManualResetEventSlim();
        using var rescue = new ManualResetEventSlim();
        using var operationReturned = new ManualResetEventSlim();
        int calls = 0;
        CancellationToken firstToken = default, secondToken = default;
        CancellationTokenRegistration registration = default;
        using var handle = service.CreateOneShot(TimeSpan.FromMilliseconds(1), ct =>
        {
            if (Interlocked.Increment(ref calls) == 1)
            {
                firstToken = ct;
                registration = ct.Register(() =>
                {
                    cancelEntered.Set();
                    if (!releaseCancel.Wait(TimeSpan.FromSeconds(30))) throw new TimeoutException("release old cancellation");
                    cancelReturned.Set();
                });
                firstEntered.Set();
                return Task.CompletedTask;
            }
            secondToken = ct;
            secondEntered.Set();
            if (WaitHandle.WaitAny(new[] { ct.WaitHandle, rescue.WaitHandle }, TimeSpan.FromSeconds(30)) == WaitHandle.WaitTimeout)
                throw new TimeoutException("new callback cancellation or rescue");
            return Task.CompletedTask;
        });
        if (!firstEntered.Wait(TimeSpan.FromSeconds(30))) throw new TimeoutException("first callback");
        var operation = Task.Factory.StartNew(() =>
        {
            if (dispose) handle.Dispose(); else handle.Stop();
            operationReturned.Set();
        }, CancellationToken.None, TaskCreationOptions.LongRunning, TaskScheduler.Default);
        if (!cancelEntered.Wait(TimeSpan.FromSeconds(30))) throw new TimeoutException("old cancellation entry");
        handle.Restart(TimeSpan.FromMilliseconds(1));
        if (!secondEntered.Wait(TimeSpan.FromSeconds(30))) throw new TimeoutException("new callback entry");
