        if (!cancelReturned.Wait(TimeSpan.FromSeconds(30))) throw new TimeoutException("old cancellation return");
        bool completedWithoutRescue = operationReturned.Wait(TimeSpan.FromSeconds(2));
        bool newTokenCanceledBeforeRescue = secondToken.IsCancellationRequested;
        rescue.Set();
        if (!operationReturned.Wait(TimeSpan.FromSeconds(30))) throw new TimeoutException("operation after rescue");
